def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    arr = []
    for _ in range(n):
        arr.append(int(next(iterator)))

    # Dictionary to store the count of each element in the current window
    count_map = {}
    left = 0
    max_len = 0

    for right in range(n):
        num = arr[right]
        count_map[num] = count_map.get(num, 0) + 1

        # If any element appears more than twice, shrink the window from the left
        while count_map[num] > 2:
            left_num = arr[left]
            count_map[left_num] -= 1
            if count_map[left_num] == 0:
                del count_map[left_num]
            left += 1

        # Update the maximum length found so far
        current_len = right - left + 1
        if current_len > max_len:
            max_len = current_len

    print(max_len)

if __name__ == "__main__":
